package org.local.donusturucu.qa;
import android.os.Bundle;import android.content.Context;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class NoisySpeech extends OcrRobustness {
 public void onStart(){Bundle result=new Bundle();try{final Context c=getTargetContext();ClassLoader loader=c.getClassLoader();Class<?>engine=Class.forName("org.local.donusturucu.SpeechEngine",true,loader),host=Class.forName("org.local.donusturucu.SpeechEngine$Host",true,loader);Constructor<?>cons=engine.getDeclaredConstructor(Context.class,host);cons.setAccessible(true);Method read=engine.getDeclaredMethod("read",File.class,String.class,double.class,double.class,File.class);read.setAccessible(true);File root=new File(c.getExternalFilesDir(null),"noisy-speech-test");root.mkdirs();JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(final String lang:new String[]{"tr","en"})for(final String kind:new String[]{"snr20","snr10"}){JSONObject row=new JSONObject();row.put("language",lang);row.put("kind",kind);row.put("repeat",repeat);try{
  String filename="noisy-"+lang+"-"+kind+".wav";File f=new File(root,filename);InputStream in=getContext().getAssets().open(filename);OutputStream out=new FileOutputStream(f);try{byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}finally{in.close();out.close();}String before=hash(f);double clip=lang.equals("tr")?6.8976875:3.160875,total=clip,start=0,end=-1;final double expected=clip;final JSONArray progress=new JSONArray();final double[]pcmDuration={0};
  Object callback=Proxy.newProxyInstance(loader,new Class<?>[]{host},new InvocationHandler(){public Object invoke(Object p,Method m,Object[]args)throws Throwable{
   if(m.getName().equals("progress")){progress.put((Double)args[0]);return null;}
   if(m.getName().equals("run")){List<String>command=new ArrayList<String>((List<String>)args[0]);command.set(0,new File(c.getApplicationInfo().nativeLibraryDir,"libffmpeg.so").toString());ProcessBuilder pb=new ProcessBuilder(command);pb.redirectErrorStream(true);pb.environment().put("LD_LIBRARY_PATH",new File(c.getFilesDir(),"ffmpeg-runtime/usr/lib")+":"+c.getApplicationInfo().nativeLibraryDir);java.lang.Process proc=pb.start();ByteArrayOutputStream b=new ByteArrayOutputStream();InputStream input=proc.getInputStream();try{byte[]buf=new byte[8192];int n;while((n=input.read(buf))!=-1)b.write(buf,0,n);}finally{input.close();}if(proc.waitFor()!=0)throw new IOException(b.toString());pcmDuration[0]=new File(command.get(command.size()-1)).length()/32000d;if(Math.abs(pcmDuration[0]-expected)>.03)throw new IOException("PCM range mismatch "+pcmDuration[0]+" vs "+expected);return null;}return null;}});
  File work=new File(root,lang+"-"+kind+"-"+repeat);work.mkdirs();long begin=System.nanoTime();String text=(String)read.invoke(cons.newInstance(c,callback),f,lang,start,end,work);row.put("text",text);row.put("seconds",(System.nanoTime()-begin)/1e9);row.put("pcm_seconds",pcmDuration[0]);row.put("progress",progress);if(kind.equals("silence")){if(!text.isEmpty())throw new IOException("Hallucinated silence");}else if(!text.toLowerCase(Locale.ROOT).contains(lang.equals("tr")?"merhaba":"repeat that"))throw new IOException("Expected speech missing");if(lang.equals("en")&&kind.equals("full")&&text.toLowerCase(Locale.ROOT).split("repeat that",-1).length-1!=12)throw new IOException("Repeated speech omitted");if(lang.equals("tr")&&kind.equals("full")&&text.toLowerCase(Locale.ROOT).split("merhaba",-1).length-1!=6)throw new IOException("Turkish greeting omitted");if(kind.equals("full")&&progress.length()<3)throw new IOException("Long audio not chunked");for(int i=1;i<progress.length();i++)if(progress.getDouble(i)<progress.getDouble(i-1)||progress.getDouble(i)-progress.getDouble(i-1)>28.01)throw new IOException("Invalid chunk boundary");if(Math.abs(progress.getDouble(progress.length()-1)-expected)>.03)throw new IOException("Incomplete progress");if(new File(work,"speech.pcm").exists())throw new IOException("PCM not cleaned");if(!before.equals(hash(f)))throw new IOException("Source changed");row.put("source_unchanged",true);row.put("pass",true);
 }catch(Throwable e){row.put("pass",false);row.put("error",e.toString());if(e instanceof InvocationTargetException)row.put("cause",((InvocationTargetException)e).getCause().toString());}rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");try{w.write(report.toString(2));}finally{w.close();}}
 result.putString("report",new File(root,"report.json").toString());finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
